/* Lot 101: color and background-color keyframes on named scroll and view timelines (generated by scripts/lot101_colorgen.py; expectations from scripts/lot101_colormodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[6144];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void prep2(const char *css, int ms, int pm) {
    wf_site_set_scroll(pm);
    prep(css, ms);
    wf_site_set_scroll(0);
    TEST_ASSERT_EQUAL(pm, g_d.scroll_pm);
}

static void test_l101_scroll_0(void) {
    prep2("@keyframes k { 60% { background-color: linen } } html { scroll-timeline: --u y, --t block; view-timeline-name: --u; view-timeline-axis: y } #o { animation: k 1s 2 forwards, k 2s 250ms 0.5; animation-timeline: --t, --t }", 0, 7500);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#faf0e6dd\"", style_of("o"));
    TEST_ASSERT_EQUAL(1, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(2, g_d.anim_scroll);
    prep2("@keyframes k { from { color: currentcolor; background-color: color-mix(in srgb, currentcolor, royalblue) } 25% { color: rebeccapurple } 50% { background-color: hwb(521grad 66% 98) } } html { scroll-timeline: --t } body { color: color( display-p3  0.97  1.7333  111.3% / 0) } #o { color: #36bb35; animation: k 0s linear; animation-timeline: --v }", 1500, 7500);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#36bb35\"", style_of("o"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_scroll);
    prep2("@keyframes k { from { color: color( srgb-linear 0.5 0.5 0.5131); background-color: hwb(283grad 100% -3%/0) } 75% { background-color: rgb(246 249 81 / 120%) } } @keyframes j { 0% { background-color: color-mix(in srgb, currentcolor, #b99) } 60% { color: color(xyz-d65  0  0.491  0.8); background-color: hwb(0.8807turn 41% 58%) } } html { scroll-timeline: --v y; scroll-timeline: auto; view-timeline: --t block } #o { animation: j 1s linear; animation-timeline: --u, --t }", 1500, 5000);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_scroll);
    prep2("@keyframes k { 25% { background-color: hwb(5.1675rad 76% 88.8%) } 100% { color: lab(32  -107  -149.9); background-color: #89addb36 } } #o { animation: j 0s linear infinite; animation-timeline: --t }", 500, 1025);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_scroll);
}

